import generated from "./sentences.generated.json";

export interface Sentence {
  /** The curriculum word this sentence puts in context: its least frequent word. */
  anchor: string;
  hanzi: string;
  id: string;
  meaning: string;
  pinyin: string;
  /** Tatoeba sentence number, or null for a sentence written for the course. */
  source: number | null;
  words: string[];
}

/** Generated by `bun run data:sync`; see src/data/README.md. */
export const sentences: Sentence[] = generated.sentences;
